fields.InputDefinition:
{
  "goal": "Open the Component Studio app using the application switcher dropdown next to the logo, then open the Components section. This shared setup is done ONCE. Then exercise these controls IN ORDER, and as you finish each set \"checkpointReached\" to the exact checkpoint name shown: (1) search-narrows — in the left browser panel's 'Search components...' box type a few characters of a likely component name (or a random string like 'zzz') and confirm the browser responds — the 'X of Y' count updates and the card list narrows to matches, or a 'No matching components' empty state appears for a non-matching query; (2) filter-panel — click the filter toggle button (a sliders icon) in the browser header controls row to expand the collapsible filter panel, confirm it renders its controls ('Favorites only' checkbox, 'Show deprecated' checkbox, and — if categories exist — category pill buttons), then toggle 'Favorites only' or a category pill and confirm the component list/count responds (or a no-results empty state). Keep going until both controls have been exercised. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "search-narrows",
      "instruction": "component search narrows the list",
      "visualCriteria": [
        "Typing in the 'Search components...' box changes the visible component list and/or the 'X of Y' count, and a non-matching query produces a 'No matching components' empty state rather than an unchanged full list"
      ]
    },
    {
      "name": "filter-panel",
      "instruction": "filter panel expands and reacts",
      "visualCriteria": [
        "Clicking the filter toggle (sliders icon) expands a filter panel showing 'Favorites only' and 'Show deprecated' options, and toggling a filter (favorites or a category pill) updates the component list or the 'X of Y' count (or shows a no-results state)"
      ]
    }
  ]
}
